package org.circus.core;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.InflaterInputStream;
/**Full original41CC90 programs against Pc1Audio plus real-memory COM resolver.
 *ABI bytes originate in actual public interfaces; code bodies here remain
 *explicit fixtures. Required boundary is not called a native process fault. */
public final class Pc1ComMachineTests {
 private static int checks;
 private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 private static int n(Object value){return(int)((Number)value).longValue();}
 private static boolean yes(Map<?,?> value,String key){return Boolean.TRUE.equals(value.get(key));}
 private static byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[4096];for(int c;(c=in.read(bytes))!=-1;)out.write(bytes,0,c);return out.toByteArray();}
 private static Pc1GuestAddressSpace.ExternalOwner key(String role,Object id)throws IOException{return new Pc1GuestAddressSpace.ExternalOwner(role,id.toString());}
 private static Pc1ComMemory.Stack stack(final int... words){return index->{if(index<0||index>=words.length)throw new IOException("Unknown fixture stack word");return words[index];};}
 private static Pc1Audio.Catalog empty(){return new Pc1Audio.Catalog(){public int musicCount(){return 0;}public int soundCount(){return 0;}public Pc1Audio.Entry music(int n)throws IOException{throw new IOException("unused");}public Pc1Audio.Entry sound(int n)throws IOException{throw new IOException("unused");}};}
 private static void region(Pc1NativeMemory bus,int address,int length)throws IOException{final byte[] bytes=new byte[length];bus.bind(address,length,new Pc1NativeMemory.Region(){public int read(int n){return bytes[n]&255;}public void write(int n,int value){bytes[n]=(byte)value;}});}
 private static final class Body implements Pc1ComMemory.Binding {
  final Output out;final Map<?,?> metadata;final int index;final Pc1ComMemory.Kind kind;int volume;boolean playing;
  Body(Output out,Map<?,?> metadata,int index){this.out=out;this.metadata=metadata;this.index=index;kind=Pc1ComMemory.Kind.valueOf(metadata.get("kind").toString());volume=index==2?17:index==3?19:0;}
  public Pc1ComMemory.Kind kind(){return kind;}public long physicalIdentity(){return 0x1100000000L+index*16;}public boolean live(){return true;}public String contractId(){return "ORIGINAL41CC90_EXPLICIT_BODY_FIXTURE_V1";}public Pc1GuestAddressSpace.ExternalOwner vtableOwner(){try{return key(Pc1ComMemory.VTABLE_OWNER,metadata.get("table"));}catch(IOException e){throw new AssertionError(e);}}
  public byte[] restorationProof()throws IOException{throw new IOException("Instruction fixture is not a physical COM adoption provider");}
  public Pc1ComMemory.Leaf leaf(int slot)throws IOException{final Pc1ComMemory.Method method=Pc1ComMemory.method(kind,slot);final Pc1GuestAddressSpace.ExternalOwner owner=key(Pc1ComMemory.CALL_OWNER,((List<?>)metadata.get("leaves")).get(slot));return new Pc1ComMemory.Leaf(){public Pc1GuestAddressSpace.ExternalOwner owner(){return owner;}public Pc1ComMemory.Method method(){return method;}public String contractId(){return "ACTUAL_ABI_INPUT_EXPLICIT_CALL_BODY_FIXTURE_V1";}public byte[] restorationProof()throws IOException{throw new IOException("No physical restoration by instruction fixture");}public int invoke(Pc1ComMemory.Binding actual,Pc1ComMemory.Stack args)throws IOException{
   Body target=(Body)actual;StringBuilder trace=new StringBuilder(method.name);for(int n=0;n<method.argumentWords;n++)trace.append(':').append(args.word(n));out.trace.add(trace.toString());switch(method.name){case "SetVolume":target.volume=args.word(1);break;case "Play":target.playing=true;break;case "Stop":target.playing=false;break;case "SetCurrentPosition":break;default:throw new IOException("Unprovided original-program call fixture "+method.name);}if(out.trace.size()==1&&yes(out.c,"switch"))out.space.writeI32(out.cell,out.objects[3].address);return 0;
  }};}
 }
 private static final class Output implements Pc1Audio.Backend {
  final Pc1GuestAddressSpace space;final Pc1ComMemory com;final Map<?,?> c;final Pc1ComMemory.ObjectRef[] objects=new Pc1ComMemory.ObjectRef[4];final Body[] bodies=new Body[4];final List<String> trace=new ArrayList<>();final int cell;
  Output(Pc1GuestAddressSpace space,Pc1ComMemory com,Map<?,?> c){this.space=space;this.com=com;this.c=c;cell=0xbc12d0+(n(c.get("slot"))+3)*4;}
  int call(int raw,int offset,int... words)throws IOException{Pc1ComMemory.Call call=com.resolveCell(0xbc12d0+raw*4,offset);int[] args=new int[words.length+1];args[0]=call.interfaceAddress;System.arraycopy(words,0,args,1,words.length);return com.invoke(call,stack(args),args.length);}
  public int setPosition(int raw,int value)throws IOException{return call(raw,52,value);}public int play(int raw,int flags)throws IOException{return call(raw,48,0,0,flags);}public boolean pcmInitialized(){return true;}
  public Pc1Audio.Loaded loadPcm(int at,byte[] raw,boolean streaming)throws IOException{throw new IOException("unused");}public int stop(int at)throws IOException{throw new IOException("unused");}public int release(int at)throws IOException{throw new IOException("unused");}public void closeStream()throws IOException{throw new IOException("unused");}public int setVolume(int at,int value)throws IOException{throw new IOException("unused");}public int playCursor(int at)throws IOException{throw new IOException("unused");}public int status(int at)throws IOException{throw new IOException("unused");}public byte[] midiPath(byte[] raw)throws IOException{throw new IOException("unused");}public int mci(byte[] raw,boolean notify)throws IOException{throw new IOException("unused");}public int setTimer(int at,int value)throws IOException{throw new IOException("unused");}public int killTimer(int at)throws IOException{throw new IOException("unused");}public boolean adoptRestoredState(Pc1Audio.State state){return false;}
 }
 private static final String VECTORS="";
 public static int run()throws Exception{
  checks=0;String text;try(InputStream in=new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(VECTORS)))){text=new String(readAll(in),StandardCharsets.UTF_8);}Map<?,?> report=(Map<?,?>)DataJson.parse(text),abi=(Map<?,?>)report.get("abi");List<?> rows=(List<?>)report.get("cases"),descriptors=(List<?>)abi.get("objects");check(rows.size()==16,"All sixteen full original41CC90 programs embedded");
  for(Object value:rows){Map<?,?> row=(Map<?,?>)value,c=(Map<?,?>)row.get("case");String id=c.get("id").toString();Pc1GuestAddressSpace space=new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1());Pc1ComMemory com=new Pc1ComMemory(space);Output out=new Output(space,com,c);final byte[] settings=new byte[Pc1NativeSettings.SIZE];Pc1NativeMemory memory=new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int n){return settings[n]&255;}public void write(int n,int v){settings[n]=(byte)v;}});memory.bindGuestAddressSpace(space);region(memory,0xbbaaf4,4);region(memory,0xbc12c8,4);region(memory,0xbc12d0,40);Pc1Audio audio=new Pc1Audio(out,empty());audio.bindNativeMemory(memory);audio.adoptAlreadyInitialized();check(space.contractIdentity().equals(abi.get("policy")),"Shared Guest ABI policy "+id);
   for(int k=0;k<4;k++){Map<?,?> descriptor=(Map<?,?>)descriptors.get(k);Body physical=new Body(out,descriptor,k);out.bodies[k]=physical;out.objects[k]=com.register(key(Pc1ComMemory.INTERFACE_OWNER,descriptor.get("owner")),physical);check(out.objects[k].address==n(descriptor.get("address")),"Actual translated ABI input allocation address "+id+"/"+k);}
   int a=out.objects[2].address,b=out.objects[3].address,at=n(c.get("slot"))+3,table=space.readI32(a);audio.writeNativeInt(0xbbaafc+at*4,c.containsKey("loaded")?n(c.get("loaded")):1);space.writeI32(out.cell,c.containsKey("pointer")?n(c.get("pointer")):a+(yes(c,"unaligned")?1:0));
   if(c.containsKey("redirect")){String kind=c.get("redirect").toString();space.writeI32(table+52,kind.equals("unknown")?0x12345678:space.readI32(table+(kind.equals("volume")?60:72)));}if(yes(c,"fake_table")){space.writeI32(a,0x454cd8+16);space.writeI32(0x454cd8+16+52,space.readI32(table+60));space.writeI32(0x454cd8+16+48,space.readI32(table+48));}if(yes(c,"fake_this")){space.writeI32(0x454cd8+16,table);space.writeI32(out.cell,0x454cd8+16);}if(yes(c,"null_table"))space.writeI32(a,0);
   String boundary=null;try{audio.startMix(n(c.get("slot")));}catch(IOException problem){String message=problem.getMessage();boundary=message.contains("cleanup")?"cleanup":message.contains("current THIS")?"this":message.contains("current raw leaf")?"leaf":"memory";}
   Map<?,?> expected=(Map<?,?>)row.get("boundary");check(expected==null?boundary==null:expected.get("kind").equals(boundary),"Exact required boundary after ordered pointer reads "+id+" got="+boundary);List<String> trace=new ArrayList<>();for(Object nativeCall:(List<?>)row.get("trace")){List<?> fields=(List<?>)nativeCall;StringBuilder call=new StringBuilder(fields.get(0).toString());for(int k=1;k<fields.size();k++)call.append(':').append(n(fields.get(k)));trace.add(call.toString());}check(out.trace.equals(trace),"Full original function selected leaves/THIS/arguments "+id+" got="+out.trace);check(space.readI32(out.cell)==n(row.get("pointer_cell")),"Inter-call native pointer-cell mutation retained "+id);check(out.bodies[2].volume==n(row.get("a_volume"))&&out.bodies[3].volume==n(row.get("b_volume")),"Selected actual fixture target gets volume side effect "+id);check(out.bodies[2].playing==yes(row,"a_playing")&&out.bodies[3].playing==yes(row,"b_playing"),"Fresh second pointer read selects correct Play target "+id);
  }return checks;
 }
 public static void main(String[] args)throws Exception{System.out.println("Pc1ComMachineTests PASS "+run()+"; original41CC90 full programs and exported actual ABI inputs; OS bodies explicit fixtures, not physical retained-graph proof");}
}
